"use client";

import { useEffect, useState } from "react";
import { useRouter } from "next/navigation";
export const dynamic = "force-dynamic";
import { auth } from "@/lib/firebase";
import { onAuthStateChanged } from "firebase/auth";
import { db } from "@/lib/firebase";
import { doc, getDoc } from "firebase/firestore";
import Link from "next/link";
import { Search, School, X, Calculator, Ruler, Monitor, BookOpen, MapPin, MessageSquare, Bell } from "lucide-react";
import { useCollege } from "@/contexts/CollegeContext";
import { COLLEGES } from "@/lib/constants";
import { motion, AnimatePresence } from "framer-motion";

export default function LandingPage() {
  const router = useRouter();
  const [checking, setChecking] = useState(true);
  const { selectedCollege, setSelectedCollege, isReady } = useCollege();

  // States for Hero Animation Sequence
  const [animationStep, setAnimationStep] = useState(0);

  useEffect(() => {
    // Auth Check
    if (!auth) { setChecking(false); return; }
    const unsub = onAuthStateChanged(auth, async (user) => {
      if (!user) { setChecking(false); return; }
      if (!db) { router.push("/home"); return; }
      try {
        const userDoc = await getDoc(doc(db, "users", user.uid));
        if (userDoc.exists() && userDoc.data()?.isVerified) {
          router.push("/home");
        } else {
          setChecking(false);
        }
      } catch {
        setChecking(false);
      }
    });

    // Start Hero Animation Loop
    const timer = setInterval(() => {
      setAnimationStep(prev => (prev + 1) % 4);
      // 0: Initial thought bubbles
      // 1: Phone Appears / Search Bar Focus
      // 2: Move Together & Trade
      // 3: Success state
    }, 3500);

    return () => {
      unsub();
      clearInterval(timer);
    };
  }, [router]);

  const handleSelectCollege = (college: any) => {
    setSelectedCollege(college);
    router.push("/home");
  };

  const [searchQuery, setSearchQuery] = useState("");

  if (checking) return null;

  return (
    <div className="flex-1 flex flex-col min-h-screen bg-[#FDFDFD] relative overflow-hidden font-sans">

      {/* ── Top Navigation (Logo + Action Block) ── */}
      <header className="absolute top-0 left-0 w-full p-6 flex justify-between items-start z-50">
        <div className="flex flex-col">
          <span className="text-2xl font-black tracking-tight text-slate-800" style={{ fontFamily: "Outfit, sans-serif" }}>Idhi Yaaparam</span>
          <span className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mt-0.5">Campus Marketplace</span>
        </div>

        {/* Sketch: Top right sticky menu block */}
        <div className="bg-white border-2 border-slate-900 rounded-2xl shadow-[4px_4px_0px_#0f172a] overflow-hidden flex flex-col font-black text-sm uppercase tracking-widest">
          <Link href="/home" className="px-5 py-2.5 border-b-2 border-slate-100 hover:bg-slate-50 transition-colors">Sell</Link>
          <Link href="/home" className="px-5 py-2.5 border-b-2 border-slate-100 hover:bg-slate-50 transition-colors">Buy</Link>
          <Link href="/home" className="px-5 py-2.5 bg-indigo-50 text-indigo-700 hover:bg-indigo-100 transition-colors">Rent</Link>
        </div>
      </header>

      {/* ── Floating SVG Elements (Inventory Background) ── */}
      <div className="absolute inset-0 pointer-events-none opacity-20 hidden md:block">
        <Monitor className="absolute top-[20%] left-[10%] w-16 h-16 text-slate-400 rotate-[-12deg]" />
        <BookOpen className="absolute top-[15%] right-[20%] w-20 h-20 text-slate-400 rotate-[15deg]" />
        <Ruler className="absolute bottom-[40%] left-[5%] w-24 h-24 text-slate-400 rotate-[-45deg]" />
        <Calculator className="absolute bottom-[35%] right-[10%] w-14 h-14 text-slate-400 rotate-[20deg]" />
      </div>

      <div className="flex-1 flex flex-col pt-28 max-w-5xl mx-auto w-full px-5 pb-20 relative">

        {/* ── Animated Hero Exchange ── */}
        <section className="relative w-full h-[350px] md:h-[450px] flex items-center justify-center mb-16">

          {/* Central App/Search element */}
          <motion.div
            initial={{ y: 50, opacity: 0, scale: 0.9 }}
            animate={{
              y: animationStep >= 1 ? 0 : 50,
              opacity: animationStep >= 1 ? 1 : 0,
              scale: animationStep >= 1 ? 1 : 0.9
            }}
            transition={{ type: "spring", bounce: 0.4 }}
            className="absolute z-30 w-full max-w-sm"
          >
            <div className="bg-white/90 backdrop-blur-xl border border-slate-200/50 p-6 rounded-[2rem] shadow-2xl items-center flex flex-col">
              <div className="w-12 h-12 bg-indigo-50 text-indigo-600 rounded-2xl flex items-center justify-center mb-4">
                <School className="w-6 h-6" />
              </div>
              <h2 className="text-xl font-black text-slate-800 text-center mb-4" style={{ fontFamily: "Outfit, sans-serif" }}>Select Your College</h2>
              <div className="relative w-full z-50">
                <Search className="w-4 h-4 absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" />
                <input
                  autoFocus
                  type="text"
                  placeholder="Search campus..."
                  value={searchQuery}
                  onChange={(e) => setSearchQuery(e.target.value)}
                  className="w-full bg-slate-50 border border-slate-200 focus:border-indigo-500 rounded-xl h-12 pl-11 pr-4 text-slate-800 font-bold outline-none text-sm pointer-events-auto"
                />
              </div>

              {/* College Results Dropdown directly embedded for fast action */}
              {searchQuery.length > 0 && (
                <div className="absolute top-full left-0 w-full mt-2 bg-white border border-slate-200 rounded-xl shadow-xl max-h-48 overflow-y-auto z-50">
                  {COLLEGES.filter(c => c.name.toLowerCase().includes(searchQuery.toLowerCase())).slice(0, 5).map(college => (
                    <button
                      key={college.id}
                      onClick={() => handleSelectCollege(college)}
                      className="w-full text-left px-4 py-3 hover:bg-slate-50 border-b border-slate-50 last:border-0"
                    >
                      <div className="font-bold text-slate-800 text-sm">{college.name}</div>
                      <div className="text-[10px] font-bold text-slate-400 uppercase">{college.state}</div>
                    </button>
                  ))}
                </div>
              )}
            </div>
          </motion.div>

          {/* Left Student (Buyer/Renter) */}
          <motion.div
            className="absolute left-[5%] md:left-[15%] z-20 flex flex-col items-center"
            animate={{
              x: animationStep >= 2 ? (typeof window !== 'undefined' && window.innerWidth < 768 ? 60 : 120) : 0
            }}
            transition={{ type: "spring", bounce: 0.2 }}
          >
            {/* Thought Bubble */}
            <AnimatePresence>
              {animationStep === 0 && (
                <motion.div
                  initial={{ opacity: 0, y: 10, scale: 0.8 }}
                  animate={{ opacity: 1, y: 0, scale: 1 }}
                  exit={{ opacity: 0, scale: 0.8, y: 10 }}
                  className="bg-slate-800 text-white text-xs md:text-sm font-bold px-4 py-2 rounded-xl rounded-bl-sm mb-3 shadow-lg whitespace-nowrap"
                >
                  "I want a drafter urgently"
                </motion.div>
              )}
            </AnimatePresence>

            <div className="w-16 h-16 md:w-24 md:h-24 bg-rose-100 rounded-full border-4 border-white shadow-xl flex items-center justify-center text-2xl md:text-3xl relative">
              👦🏽
              {/* Product Received Animation */}
              <AnimatePresence>
                {animationStep === 3 && (
                  <motion.div
                    initial={{ scale: 0, y: -20, opacity: 0 }}
                    animate={{ scale: 1, y: -40, opacity: 1 }}
                    exit={{ opacity: 0 }}
                    className="absolute -top-4 w-10 h-10 bg-white rounded-xl shadow-lg flex items-center justify-center border-2 border-slate-100"
                  >
                    <Ruler className="w-5 h-5 text-indigo-500" />
                  </motion.div>
                )}
              </AnimatePresence>
            </div>
            <span className="font-bold text-[10px] uppercase tracking-widest text-slate-500 mt-3 bg-white px-2 py-0.5 rounded-full shadow-sm">Borrower</span>
          </motion.div>

          {/* Right Student (Owner) */}
          <motion.div
            className="absolute right-[5%] md:right-[15%] z-20 flex flex-col items-center"
            animate={{
              x: animationStep >= 2 ? (typeof window !== 'undefined' && window.innerWidth < 768 ? -60 : -120) : 0
            }}
            transition={{ type: "spring", bounce: 0.2 }}
          >
            {/* Thought Bubble */}
            <AnimatePresence>
              {animationStep === 0 && (
                <motion.div
                  initial={{ opacity: 0, y: 10, scale: 0.8 }}
                  animate={{ opacity: 1, y: 0, scale: 1 }}
                  exit={{ opacity: 0, scale: 0.8, y: 10 }}
                  className="bg-indigo-600 text-white text-xs md:text-sm font-bold px-4 py-2 rounded-xl rounded-br-sm mb-3 shadow-lg whitespace-nowrap"
                >
                  "I want to rent my drafter"
                </motion.div>
              )}
            </AnimatePresence>

            <div className="w-16 h-16 md:w-24 md:h-24 bg-emerald-100 rounded-full border-4 border-white shadow-xl flex items-center justify-center text-2xl md:text-3xl relative">
              👩🏻‍🦱
              {/* Product Held / Money Received */}
              <AnimatePresence mode="wait">
                {animationStep < 3 ? (
                  <motion.div
                    key="holding"
                    exit={{ opacity: 0, scale: 0 }}
                    className="absolute -top-4 w-10 h-10 bg-white rounded-xl shadow-lg flex items-center justify-center border-2 border-slate-100"
                  >
                    <Ruler className="w-5 h-5 text-indigo-500" />
                  </motion.div>
                ) : (
                  <motion.div
                    key="paid"
                    initial={{ scale: 0, y: 0 }}
                    animate={{ scale: 1, y: -40 }}
                    className="absolute -top-4 bg-emerald-500 text-white font-black text-xs px-2 py-1 rounded-lg shadow-lg flex items-center whitespace-nowrap"
                  >
                    + ₹20
                  </motion.div>
                )}
              </AnimatePresence>
            </div>
            <span className="font-bold text-[10px] uppercase tracking-widest text-slate-500 mt-3 bg-white px-2 py-0.5 rounded-full shadow-sm">Owner</span>
          </motion.div>

        </section>


        {/* ── Campus Radar Concept (Sketch Bottom Half) ── */}
        <section className="relative w-full bg-slate-50 rounded-[3rem] p-8 md:p-12 border-2 border-dashed border-slate-200 mt-8">

          <h3 className="text-xl font-black text-slate-800 mb-8 text-center uppercase tracking-widest opacity-40">Campus Radar Loop</h3>

          <div className="relative w-full h-[400px] max-w-2xl mx-auto">

            {/* Center User (Me) */}
            <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 flex flex-col items-center z-20">
              <div className="w-16 h-16 bg-blue-500 text-white rounded-full flex items-center justify-center text-xl shadow-xl shadow-blue-500/20 border-4 border-white relative">
                Me
                <div className="absolute -inset-8 border border-blue-500/20 rounded-full animate-ping" />
                <div className="absolute -inset-16 border border-blue-500/10 rounded-full animate-ping" style={{ animationDelay: '0.5s' }} />
              </div>
            </div>

            {/* CSC Department User */}
            <div className="absolute top-[10%] left-[10%] group">
              <div className="relative">
                <div className="absolute -top-12 left-1/2 -translate-x-1/2 bg-white px-3 py-1.5 rounded-xl shadow-lg pointer-events-none opacity-0 group-hover:opacity-100 transition-opacity whitespace-nowrap z-30 flex items-center gap-2">
                  <MessageSquare className="w-3 h-3 text-emerald-500" />
                  <span className="text-xs font-bold text-slate-700">Has Laptop</span>
                </div>
                <div className="w-12 h-12 bg-amber-100 rounded-full border border-white shadow-md flex items-center justify-center text-lg z-20 relative">👨🏽‍🎓</div>
              </div>
              <div className="mt-2 text-center">
                <div className="text-[10px] font-black text-slate-500 uppercase tracking-wider">CSC Dept</div>
                <div className="text-[9px] font-bold text-slate-400 bg-slate-100 px-1.5 rounded inline-block mt-0.5"><MapPin className="w-2 h-2 inline mr-0.5" />200m</div>
              </div>
            </div>

            {/* Mechanical Department User */}
            <div className="absolute bottom-[20%] left-[5%] group">
              <div className="relative">
                <div className="absolute -top-14 left-1/2 -translate-x-1/2 bg-white px-3 py-2 rounded-xl shadow-lg z-30 whitespace-nowrap border border-slate-100">
                  <span className="text-xs font-bold text-slate-700 block">I want calci/drafter</span>
                  <div className="absolute -bottom-1.5 left-1/2 -translate-x-1/2 w-3 h-3 bg-white rotate-45 border-r border-b border-slate-100" />
                </div>
                <div className="w-12 h-12 bg-rose-100 rounded-full border border-white shadow-md flex items-center justify-center text-lg z-20 relative mt-4">👷🏽‍♂️</div>
              </div>
              <div className="mt-2 text-center">
                <div className="text-[10px] font-black text-slate-500 uppercase tracking-wider">Mech Dept</div>
                <div className="text-[9px] font-bold text-slate-400 bg-slate-100 px-1.5 rounded inline-block mt-0.5"><MapPin className="w-2 h-2 inline mr-0.5" />300m</div>
              </div>
            </div>

            {/* IT Department User */}
            <div className="absolute top-[30%] right-[10%] group">
              <div className="relative">
                <div className="absolute -top-10 -right-20 bg-indigo-600 px-3 py-1.5 rounded-xl shadow-lg z-30 flex items-center gap-2 whitespace-nowrap animate-bounce">
                  <Bell className="w-3 h-3 text-white fill-current" />
                  <span className="text-xs font-bold text-white">Got a notification</span>
                </div>
                <div className="w-12 h-12 bg-purple-100 rounded-full border border-white shadow-md flex items-center justify-center text-lg z-20 relative">👩🏽‍💻</div>
                <div className="absolute top-1/2 -left-20 -translate-y-1/2 bg-white/80 backdrop-blur-sm border border-slate-200 px-2 py-1 rounded text-[9px] font-bold text-slate-600 whitespace-nowrap">
                  He is near to you →
                </div>
              </div>
              <div className="mt-2 text-center">
                <div className="text-[10px] font-black text-slate-500 uppercase tracking-wider">IT Dept</div>
                <div className="text-[9px] font-bold text-slate-400 bg-slate-100 px-1.5 rounded inline-block mt-0.5"><MapPin className="w-2 h-2 inline mr-0.5" />50m</div>
              </div>
            </div>

          </div>
        </section>

      </div>
    </div>
  );
}

"use client";

import { useState, useEffect } from "react";
import { useParams, useRouter } from "next/navigation";
export const dynamic = "force-dynamic";
import { db, auth } from "@/lib/firebase";
import { doc, getDoc, updateDoc, addDoc, collection, serverTimestamp } from "firebase/firestore";
import { toast } from "sonner";
import {
    ChevronLeft, MapPin, Clock, IndianRupee, ShieldCheck,
    Loader2, CheckCircle2, Package, AlertTriangle, X, Send
} from "lucide-react";
import { Listing, ReportReason } from "@/lib/types";

const REPORT_REASONS: ReportReason[] = [
    "Item not returned",
    "Item damaged",
    "No-show",
    "Fraud",
    "Other",
];

const STATUS_CONFIG: Record<string, { label: string; color: string }> = {
    available: { label: "Available", color: "bg-emerald-100 text-emerald-700 border-emerald-200" },
    requested: { label: "Pending", color: "bg-amber-100 text-amber-700 border-amber-200" },
    active: { label: "Active", color: "bg-indigo-100 text-indigo-700 border-indigo-200" },
    completed: { label: "Completed", color: "bg-emerald-100 text-emerald-700 border-emerald-200" },
    cancelled: { label: "Cancelled", color: "bg-rose-100 text-rose-700 border-rose-200" },
};

export default function RentalDetailPage() {
    const { id } = useParams();
    const [rental, setRental] = useState<Listing | null>(null);
    const [loading, setLoading] = useState(true);
    const [actionLoading, setActionLoading] = useState(false);
    const [showReportModal, setShowReportModal] = useState(false);
    const [reportReason, setReportReason] = useState<ReportReason | "">("");
    const [reportNotes, setReportNotes] = useState("");

    const router = useRouter();
    const userId = auth?.currentUser?.uid;

    useEffect(() => {
        async function fetchRental() {
            if (!id || !db) return;
            try {
                const snap = await getDoc(doc(db, "rentals", id as string));
                if (snap.exists()) {
                    setRental({ id: snap.id, ...snap.data() } as Listing);
                } else {
                    toast.error("Rental not found");
                    router.push("/home");
                }
            } catch { toast.error("Error loading rental"); }
            finally { setLoading(false); }
        }
        fetchRental();
    }, [id, router]);

    const updateStatus = async (newStatus: string, extraFields: Record<string, any> = {}) => {
        if (!db || !id) return;
        setActionLoading(true);
        try {
            await updateDoc(doc(db, "rentals", id as string), {
                status: newStatus,
                ...extraFields,
            });
            setRental(r => r ? { ...r, status: newStatus as any, ...extraFields } : r);
        } catch { toast.error("Action failed. Try again."); }
        finally { setActionLoading(false); }
    };

    const handleRequest = async () => {
        if (!userId) { toast.error("Please sign in first"); return; }
        await updateStatus("requested", { renterId: userId, requestedAt: serverTimestamp() });
        toast.success("Request sent to owner! 🎉");
    };

    const handleApprove = async () => {
        await updateStatus("active", { approvedAt: serverTimestamp() });
        toast.success("Rental approved!");
    };

    const handleMarkReturned = async () => {
        await updateStatus("completed", { completedAt: serverTimestamp() });
        toast.success("Rental marked as complete!");
    };

    const handleReport = async () => {
        if (!reportReason) { toast.error("Please select a reason"); return; }
        if (!db || !userId || !rental) return;

        setActionLoading(true);
        try {
            // 1. Write report
            await addDoc(collection(db, "reports"), {
                rentalId: id,
                reporterId: userId,
                reportedUserId: rental.renterId,
                reason: reportReason,
                notes: reportNotes,
                timestamp: serverTimestamp(),
                status: "pending",
            });

            // 2. Fetch renter's doc and increment strike
            if (rental.renterId) {
                const renterRef = doc(db, "users", rental.renterId);
                const renterSnap = await getDoc(renterRef);
                if (renterSnap.exists()) {
                    const currentStrikes = renterSnap.data().strikeCount || 0;
                    const newStrikes = currentStrikes + 1;
                    await updateDoc(renterRef, {
                        strikeCount: newStrikes,
                        ...(newStrikes >= 2 ? { isBlocked: true } : {}),
                    });
                    if (newStrikes >= 2) {
                        toast.warning("User has been automatically blocked (2 strikes reached).");
                    } else {
                        toast.success(`Report submitted. User warned (Strike ${newStrikes}/2).`);
                    }
                }
            }
            setShowReportModal(false);
            setReportReason("");
            setReportNotes("");
        } catch { toast.error("Failed to submit report."); }
        finally { setActionLoading(false); }
    };

    if (loading) return (
        <div className="flex-1 flex items-center justify-center min-h-screen bg-slate-50">
            <Loader2 className="w-8 h-8 animate-spin text-indigo-400" />
        </div>
    );

    const isOwner = rental?.ownerId === userId;
    const isRenter = rental?.renterId === userId;
    const statusConf = STATUS_CONFIG[rental?.status || "available"];

    return (
        <div className="flex-1 flex flex-col min-h-screen pb-24 bg-slate-50">
            {/* Hero Image */}
            <div className="relative w-full bg-slate-200" style={{ aspectRatio: "16/9" }}>
                <img
                    src={rental?.photoUrl || `https://placehold.co/400x225/e2e8f0/4f46e5?text=${encodeURIComponent(rental?.icon || "📦")}`}
                    alt={rental?.itemName}
                    className="w-full h-full object-cover"
                />
                {/* Gradient overlay */}
                <div className="absolute inset-0" style={{ background: "linear-gradient(to bottom, rgba(255,255,255,0.1) 0%, rgba(255,255,255,0) 40%)" }} />

                {/* Back button */}
                <button
                    onClick={() => router.back()}
                    className="absolute top-5 left-5 p-2.5 bg-white/60 backdrop-blur-md rounded-xl border border-white/50 active:scale-95 transition-all shadow-sm"
                >
                    <ChevronLeft className="w-5 h-5 text-slate-700" />
                </button>

                {/* Status badge */}
                <div className={`absolute top-5 right-5 px-3 py-1.5 rounded-full text-xs font-bold uppercase tracking-wider border shadow-sm ${statusConf.color}`}>
                    {statusConf.label}
                </div>
            </div>

            {/* Content sheet */}
            <div className="flex-1 px-5 pt-6 -mt-4 bg-slate-50 rounded-t-3xl relative z-10 border-t border-white shadow-[0_-10px_20px_-10px_rgba(0,0,0,0.05)]">

                {/* Title & price */}
                <div className="flex items-start justify-between mb-6">
                    <div className="space-y-1 flex-1 mr-4">
                        <span className="text-3xl drop-shadow-sm">{rental?.icon}</span>
                        <h1 className="text-2xl font-black text-slate-800 leading-tight mt-1" style={{ fontFamily: "Outfit, sans-serif" }}>
                            {rental?.itemName}
                        </h1>
                        <div className="flex items-center gap-1.5 text-indigo-500">
                            <MapPin className="w-3.5 h-3.5" />
                            <span className="text-xs font-bold uppercase tracking-wider">{rental?.block}</span>
                        </div>
                    </div>
                    <div className="bg-amber-50 border border-amber-100 p-4 rounded-2xl text-center min-w-[88px] shadow-sm">
                        <p className="text-[9px] font-bold text-amber-500 uppercase tracking-widest mb-1">Per Hour</p>
                        <div className="flex items-center justify-center gap-0.5 text-amber-600">
                            <IndianRupee className="w-3.5 h-3.5" />
                            <span className="text-xl font-black">{rental?.pricePerHour}</span>
                        </div>
                    </div>
                </div>

                {/* Info grid */}
                <div className="grid grid-cols-2 gap-3 mb-6">
                    <div className="bg-white/70 backdrop-blur-md rounded-2xl p-4 border border-white shadow-sm hover:shadow-md transition-shadow">
                        <p className="text-[9px] font-bold text-slate-400 uppercase tracking-widest mb-1.5">Trust Score</p>
                        <div className="flex items-center gap-1.5 text-emerald-600">
                            <ShieldCheck className="w-4 h-4" />
                            <span className="text-sm font-black">Verified</span>
                        </div>
                    </div>
                    <div className="bg-white/70 backdrop-blur-md rounded-2xl p-4 border border-white shadow-sm hover:shadow-md transition-shadow">
                        <p className="text-[9px] font-bold text-slate-400 uppercase tracking-widest mb-1.5">Availability</p>
                        <div className="flex items-center gap-1.5 text-slate-700">
                            <Clock className="w-4 h-4 text-indigo-500" />
                            <span className="text-sm font-black">Until 5 PM</span>
                        </div>
                    </div>
                </div>

                {/* Description */}
                <div className="bg-white/70 backdrop-blur-md rounded-2xl p-4 border border-white shadow-sm mb-8">
                    <p className="text-[9px] font-bold text-slate-400 uppercase tracking-widest mb-2">Details</p>
                    <p className="text-slate-600 text-sm leading-relaxed font-medium">
                        Top condition {rental?.itemName} available in {rental?.block}. Return on time to maintain your trust score.
                    </p>
                </div>
            </div>

            {/* ─── Fixed Action Bar ─── */}
            <div className="fixed bottom-0 left-0 right-0 bg-white/80 backdrop-blur-xl border-t border-indigo-50 px-5 py-4 max-w-md mx-auto z-50 pb-safe">
                {isOwner ? (
                    <div className="space-y-3">
                        {rental?.status === "requested" ? (
                            <div className="space-y-2">
                                <p className="text-xs font-bold text-amber-500 text-center uppercase tracking-widest">
                                    Renter is waiting for approval
                                </p>
                                <button
                                    onClick={handleApprove}
                                    disabled={actionLoading}
                                    className="w-full h-14 rounded-2xl gradient-indigo text-white font-black text-base shadow-indigo flex items-center justify-center gap-2 disabled:opacity-60 active:scale-[0.98] transition-all hover:-translate-y-0.5"
                                >
                                    {actionLoading ? <Loader2 className="animate-spin w-5 h-5" /> : <><CheckCircle2 className="w-5 h-5" /> APPROVE RENTAL</>}
                                </button>
                            </div>
                        ) : rental?.status === "active" ? (
                            <button
                                onClick={handleMarkReturned}
                                disabled={actionLoading}
                                className="w-full h-14 rounded-2xl bg-emerald-500 text-white font-black text-base flex items-center justify-center gap-2 disabled:opacity-60 active:scale-[0.98] transition-all hover:bg-emerald-600 shadow-sm"
                            >
                                {actionLoading ? <Loader2 className="animate-spin w-5 h-5" /> : <><Package className="w-5 h-5" /> MARK AS RETURNED</>}
                            </button>
                        ) : rental?.status === "completed" ? (
                            <div className="flex flex-col items-center gap-2">
                                <div className="flex items-center gap-2 bg-emerald-50 text-emerald-600 border border-emerald-100 px-4 py-2 rounded-full text-sm font-bold shadow-sm">
                                    <CheckCircle2 className="w-4 h-4" /> Rental Complete
                                </div>
                                <button
                                    onClick={() => setShowReportModal(true)}
                                    className="text-xs font-bold text-rose-500 hover:text-rose-600 transition-colors"
                                >
                                    Report an issue
                                </button>
                            </div>
                        ) : (
                            <div className="h-14 rounded-2xl bg-slate-100 border border-slate-200 flex items-center justify-center shadow-inner">
                                <span className="text-slate-400 font-black text-sm uppercase tracking-widest">YOUR LISTING</span>
                            </div>
                        )}
                    </div>
                ) : rental?.status === "available" ? (
                    <button
                        onClick={handleRequest}
                        disabled={actionLoading}
                        className="w-full h-14 rounded-2xl gradient-indigo text-white font-black text-base shadow-indigo flex items-center justify-center gap-2 disabled:opacity-60 active:scale-[0.98] transition-all hover:-translate-y-0.5"
                    >
                        {actionLoading ? <Loader2 className="animate-spin w-5 h-5" /> : "REQUEST NOW →"}
                    </button>
                ) : isRenter && rental?.status === "requested" ? (
                    <div className="text-center py-3">
                        <span className="bg-amber-100 text-amber-700 border border-amber-200 px-4 py-2 rounded-full text-sm font-bold shadow-sm">Awaiting owner approval...</span>
                    </div>
                ) : isRenter && rental?.status === "active" ? (
                    <div className="text-center py-3">
                        <span className="bg-indigo-100 text-indigo-700 border border-indigo-200 px-4 py-2 rounded-full text-sm font-bold shadow-sm">Rental is Active — return on time!</span>
                    </div>
                ) : (
                    <div className="h-14 rounded-2xl bg-slate-100 border border-slate-200 flex items-center justify-center shadow-inner">
                        <span className="text-slate-400 font-black text-sm uppercase tracking-widest">CURRENTLY TAKEN</span>
                    </div>
                )}
            </div>

            {/* ─── Report Modal ─── */}
            {showReportModal && (
                <div className="fixed inset-0 z-[100] flex items-end justify-center max-w-md mx-auto">
                    <div className="absolute inset-0 bg-slate-800/40 backdrop-blur-sm" onClick={() => setShowReportModal(false)} />
                    <div className="relative w-full bg-slate-50 border-t border-indigo-100 rounded-t-[2rem] p-6 space-y-5 z-10 shadow-2xl">
                        <div className="flex items-center justify-between">
                            <div>
                                <h3 className="text-lg font-black text-slate-800" style={{ fontFamily: "Outfit, sans-serif" }}>Report an Issue</h3>
                                <p className="text-xs text-slate-500 mt-0.5 font-medium">Select the reason for your report</p>
                            </div>
                            <button onClick={() => setShowReportModal(false)} className="p-2.5 rounded-xl bg-white border border-slate-200 hover:bg-slate-50 transition-colors shadow-sm">
                                <X className="w-4 h-4 text-slate-400" />
                            </button>
                        </div>

                        <div className="space-y-2">
                            {REPORT_REASONS.map((reason) => (
                                <button
                                    key={reason}
                                    onClick={() => setReportReason(reason)}
                                    className={`w-full flex items-center justify-between px-4 py-3 rounded-xl border-2 text-sm font-bold transition-all shadow-sm ${reportReason === reason
                                        ? "bg-rose-50 border-rose-200 text-rose-600"
                                        : "bg-white border-slate-100 text-slate-600 hover:border-slate-200"
                                        }`}
                                >
                                    {reason}
                                    {reportReason === reason && <AlertTriangle className="w-4 h-4 opacity-70" />}
                                </button>
                            ))}
                        </div>

                        <div>
                            <textarea
                                placeholder="Additional notes (optional)..."
                                value={reportNotes}
                                onChange={(e) => setReportNotes(e.target.value)}
                                className="w-full h-24 bg-white border border-slate-200 rounded-2xl px-4 py-3 text-sm text-slate-800 placeholder-slate-400 outline-none focus:border-rose-300 focus:ring-4 focus:ring-rose-50 resize-none shadow-inner transition-all"
                            />
                        </div>

                        <button
                            onClick={handleReport}
                            disabled={actionLoading || !reportReason}
                            className="w-full h-14 rounded-2xl bg-rose-500 text-white font-black flex items-center justify-center gap-2 disabled:opacity-50 active:scale-[0.98] transition-all hover:bg-rose-600 shadow-sm"
                        >
                            {actionLoading ? <Loader2 className="animate-spin w-5 h-5" /> : <><Send className="w-4 h-4" /> SUBMIT REPORT</>}
                        </button>
                    </div>
                </div>
            )}
        </div>
    );
}

"use client";

import { useState, useEffect } from "react";
import { useRouter } from "next/navigation";
export const dynamic = "force-dynamic";
import { db, auth, storage } from "@/lib/firebase";
import { collection, addDoc, serverTimestamp, getDoc, doc } from "firebase/firestore";
import { ref, uploadBytes, getDownloadURL } from "firebase/storage";
import { toast } from "sonner";
import { Camera, ChevronLeft, Loader2, IndianRupee, MapPin, School, GraduationCap } from "lucide-react";
import { useCollege } from "@/contexts/CollegeContext";
import { BLOCKS, DEPARTMENTS } from "@/lib/constants";

const ITEM_SUGGESTIONS = ["Casio fx991", "Drafter", "Mini Drafter", "Geometry Box", "Physics Lab Record", "Chemistry Lab Record", "Arduino Uno", "Multimeter"];
const CATEGORIES = ["Calculator", "Drafter", "Stationery", "Books/Manuals", "Electronics", "Other"];

export default function NewRentalPage() {
    const [loading, setLoading] = useState(false);
    const [name, setName] = useState("");
    const [category, setCategory] = useState(CATEGORIES[0]);
    const [price, setPrice] = useState("");
    const [block, setBlock] = useState(BLOCKS[0]);
    const [department, setDepartment] = useState(DEPARTMENTS[0]);
    const [image, setImage] = useState<File | null>(null);
    const [preview, setPreview] = useState<string | null>(null);
    const [userDept, setUserDept] = useState("");

    const router = useRouter();
    const { selectedCollege, isReady } = useCollege();

    // Fetch user profile settings if any
    useEffect(() => {
        const currentUser = auth?.currentUser;
        if (!currentUser || !db) return;
        getDoc(doc(db, "users", currentUser.uid)).then(docSnap => {
            if (docSnap.exists()) {
                const data = docSnap.data();
                if (data.department) setUserDept(data.department);
                if (data.department && DEPARTMENTS.includes(data.department)) {
                    setDepartment(data.department);
                }
            }
        });
    }, []);

    const handleImageChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        const file = e.target.files?.[0];
        if (file) {
            setImage(file);
            const reader = new FileReader();
            reader.onloadend = () => setPreview(reader.result as string);
            reader.readAsDataURL(file);
        }
    };

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        if (!name || !price || !image || !selectedCollege) {
            toast.error("Fill all fields and add a photo");
            return;
        }
        setLoading(true);
        try {
            const userId = auth?.currentUser?.uid;
            if (!userId || !storage || !db) throw new Error("Init error");
            const storageRef = ref(storage, `rentals/${Date.now()}_${userId}.jpg`);
            await uploadBytes(storageRef, image);
            const photoUrl = await getDownloadURL(storageRef);

            // basic icon mapper
            const iconMap: Record<string, string> = { "Calculator": "🧮", "Drafter": "📐", "Stationery": "📏", "Books/Manuals": "📓", "Electronics": "⚡", "Other": "📦" };

            await addDoc(collection(db, "rentals"), {
                ownerId: userId,
                itemName: name,
                pricePerHour: parseInt(price),
                block,
                college: selectedCollege.name,
                collegeId: selectedCollege.id,
                department,
                icon: iconMap[category] || "📦",
                photoUrl,
                status: "available",
                renterId: null,
                createdAt: serverTimestamp(),
            });
            toast.success("Item listed successfully! 🎉");
            router.push("/home");
        } catch (error) {
            toast.error("Failed to list item. Try again.");
        } finally {
            setLoading(false);
        }
    };

    if (isReady && !selectedCollege) {
        return (
            <div className="flex-1 flex flex-col items-center justify-center min-h-screen text-center px-6 bg-slate-50">
                <span className="text-5xl text-indigo-200 mb-6 drop-shadow-sm">🎓</span>
                <h2 className="text-2xl font-black text-slate-800 mb-2" style={{ fontFamily: "Outfit, sans-serif" }}>Select a Campus</h2>
                <p className="text-sm font-semibold text-slate-500 mb-8 max-w-[280px]">You must select a college from the home page top bar to list an item.</p>
                <button onClick={() => router.push("/home")} className="gradient-indigo text-white px-8 py-3.5 rounded-2xl font-bold shadow-indigo hover:-translate-y-0.5 transition-transform active:scale-95">Go to Home</button>
            </div>
        )
    }

    return (
        <div className="flex-1 flex flex-col min-h-screen bg-slate-50 relative overflow-y-auto">
            {/* Ambient Background Blobs */}
            <div className="absolute top-[-10%] left-[-10%] w-[50%] h-[50%] bg-blue-200/40 blob rounded-full mix-blend-multiply filter blur-3xl animate-float" style={{ animationDelay: "0s" }} />
            <div className="absolute top-[20%] right-[-10%] w-[40%] h-[60%] bg-pink-200/30 blob rounded-full mix-blend-multiply filter blur-3xl animate-float" style={{ animationDelay: "2s" }} />

            {/* Header */}
            <header className="px-5 pt-12 pb-6 flex items-center gap-4 border-b border-indigo-100 bg-white/60 backdrop-blur-md sticky top-0 z-20">
                <button
                    onClick={() => router.back()}
                    className="p-2.5 bg-white border border-indigo-100 rounded-xl active:scale-95 transition-all text-slate-500 hover:text-indigo-600 shadow-sm"
                >
                    <ChevronLeft className="w-5 h-5" />
                </button>
                <div>
                    <h1 className="text-2xl font-black text-slate-800 leading-none" style={{ fontFamily: "Outfit, sans-serif" }}>Rent Your Item</h1>
                    <p className="text-[11px] font-black text-indigo-500 uppercase tracking-widest mt-1.5">Earn by lending</p>
                </div>
            </header>

            <form onSubmit={handleSubmit} className="flex-1 px-5 space-y-7 py-8 pb-16 relative z-10 max-w-md mx-auto w-full">

                {/* College Read-only */}
                <div className="flex items-center gap-4 p-5 bg-white/70 backdrop-blur-xl rounded-3xl border border-indigo-50 shadow-sm relative overflow-hidden">
                    <div className="absolute top-0 right-0 w-32 h-32 bg-indigo-500/5 rounded-full blur-2xl -mr-16 -mt-16 pointer-events-none" />
                    <div className="w-12 h-12 rounded-2xl bg-indigo-50 border border-indigo-100 flex items-center justify-center shrink-0 shadow-inner">
                        <School className="w-6 h-6 text-indigo-500" />
                    </div>
                    <div>
                        <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Listing in Campus</p>
                        <p className="text-[15px] font-bold text-indigo-700 mt-0.5">{selectedCollege?.name}</p>
                    </div>
                </div>

                {/* Photo Upload */}
                <div className="space-y-2.5">
                    <label className="text-[11px] font-black uppercase tracking-widest text-slate-500 pl-1">Item Photo *</label>
                    <div
                        onClick={() => document.getElementById("photo-input")?.click()}
                        className="aspect-[4/3] rounded-[2rem] border-2 border-dashed border-indigo-200 bg-white/50 flex flex-col items-center justify-center relative overflow-hidden group active:scale-[0.99] transition-all cursor-pointer hover:border-indigo-400 hover:bg-slate-50 shadow-inner"
                    >
                        {preview ? (
                            <>
                                <img src={preview} alt="Preview" className="w-full h-full object-cover" />
                                <div className="absolute inset-0 bg-white/40 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center backdrop-blur-sm">
                                    <div className="p-4 bg-white rounded-full shadow-lg">
                                        <Camera className="w-8 h-8 text-indigo-600" />
                                    </div>
                                </div>
                            </>
                        ) : (
                            <div className="flex flex-col items-center gap-4 p-6 text-center">
                                <div className="p-4 bg-indigo-50 rounded-2xl group-hover:bg-indigo-100 group-hover:scale-110 transition-all text-indigo-400">
                                    <Camera className="w-8 h-8 group-hover:text-indigo-600 transition-colors" />
                                </div>
                                <div>
                                    <p className="text-[15px] font-bold text-slate-700">Tap to upload a clear photo</p>
                                    <p className="text-xs font-semibold text-slate-400 mt-1">Show any scratches or defects</p>
                                </div>
                            </div>
                        )}
                        <input id="photo-input" type="file" accept="image/*" className="hidden" onChange={handleImageChange} />
                    </div>
                </div>

                {/* Item Name */}
                <div className="space-y-2.5">
                    <label className="text-[11px] font-black uppercase tracking-widest text-slate-500 flex justify-between pl-1">
                        <span>Item Name *</span>
                    </label>
                    <input
                        type="text"
                        placeholder="e.g. Casio fx-991EX"
                        list="item-suggestions"
                        className="w-full bg-white/70 backdrop-blur-md border border-indigo-50 focus:border-indigo-400 focus:bg-white focus:ring-4 focus:ring-indigo-100 rounded-2xl h-14 px-5 text-slate-800 placeholder-slate-400 font-bold outline-none transition-all shadow-inner"
                        value={name}
                        onChange={(e) => setName(e.target.value)}
                    />
                    <datalist id="item-suggestions">
                        {ITEM_SUGGESTIONS.map(s => <option key={s} value={s} />)}
                    </datalist>
                </div>

                {/* Category & Price Row */}
                <div className="flex gap-4">
                    <div className="space-y-2.5 flex-1">
                        <label className="text-[11px] font-black uppercase tracking-widest text-slate-500 pl-1">Category *</label>
                        <select
                            value={category}
                            onChange={e => setCategory(e.target.value)}
                            className="w-full bg-white/70 backdrop-blur-md border border-indigo-50 focus:border-indigo-400 focus:bg-white focus:ring-4 focus:ring-indigo-100 rounded-2xl h-14 px-4 text-slate-700 font-bold outline-none appearance-none shadow-inner transition-all"
                        >
                            {CATEGORIES.map(c => <option key={c} value={c}>{c}</option>)}
                        </select>
                    </div>
                    <div className="space-y-2.5 w-1/2">
                        <label className="text-[11px] font-black uppercase tracking-widest text-slate-500 pl-1">Price / hr *</label>
                        <div className="flex items-center gap-2 bg-white/70 backdrop-blur-md rounded-2xl border border-indigo-50 focus-within:border-indigo-400 focus-within:bg-white focus-within:ring-4 focus-within:ring-indigo-100 h-14 px-4 shadow-inner transition-all">
                            <IndianRupee className="w-5 h-5 text-indigo-500 shrink-0" />
                            <input
                                type="number"
                                placeholder="20"
                                min="0"
                                className="w-full bg-transparent text-slate-800 placeholder-slate-400 font-black text-lg outline-none"
                                value={price}
                                onChange={(e) => setPrice(e.target.value)}
                            />
                        </div>
                    </div>
                </div>

                <div className="space-y-2.5 flex-1">
                    <label className="text-[11px] font-black uppercase tracking-widest text-slate-500 flex items-center gap-1.5 pl-1">
                        <GraduationCap className="w-3.5 h-3.5" /> Department
                    </label>
                    <select
                        value={department}
                        onChange={e => setDepartment(e.target.value)}
                        className="w-full bg-white/70 backdrop-blur-md border border-indigo-50 focus:border-indigo-400 focus:bg-white focus:ring-4 focus:ring-indigo-100 rounded-2xl h-14 px-4 text-slate-700 font-bold outline-none appearance-none shadow-inner transition-all"
                    >
                        {DEPARTMENTS.map(d => <option key={d} value={d}>{d}</option>)}
                    </select>
                </div>

                <div className="space-y-2.5 flex-1">
                    <label className="text-[11px] font-black uppercase tracking-widest text-slate-500 flex items-center gap-1.5 pl-1">
                        <MapPin className="w-3.5 h-3.5" /> Block
                    </label>
                    <select
                        value={block}
                        onChange={e => setBlock(e.target.value)}
                        className="w-full bg-white/70 backdrop-blur-md border border-indigo-50 focus:border-indigo-400 focus:bg-white focus:ring-4 focus:ring-indigo-100 rounded-2xl h-14 px-4 text-slate-700 font-bold outline-none appearance-none shadow-inner transition-all"
                    >
                        {BLOCKS.map(b => <option key={b} value={b}>{b}</option>)}
                    </select>
                </div>

                {/* Submit */}
                <div className="pt-8">
                    <button
                        type="submit"
                        disabled={loading}
                        className="w-full h-16 rounded-2xl gradient-indigo text-white font-black text-base shadow-indigo flex items-center justify-center gap-2 disabled:opacity-50 disabled:cursor-not-allowed active:scale-[0.98] hover:-translate-y-1 transition-all"
                    >
                        {loading ? <Loader2 className="animate-spin w-6 h-6" /> : "Publish Listing"}
                    </button>
                    <p className="text-center text-[10px] text-slate-400 mt-5 uppercase tracking-widest font-black">
                        By listing, you agree to the <span className="text-indigo-400">2-Strike Campus Policy</span>
                    </p>
                </div>
            </form>
        </div>
    );
}

"use client";

import { useState, useEffect } from "react";
export const dynamic = "force-dynamic";
import { db, auth } from "@/lib/firebase";
import { collection, query, where, onSnapshot, doc, updateDoc, addDoc, serverTimestamp, getDoc } from "firebase/firestore";
import { Button } from "@/components/ui/button";
import { BottomNav } from "@/components/layout/BottomNav";
import { toast } from "sonner";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { Check, X, Clock, ArrowRightLeft, PackageCheck, Loader2 } from "lucide-react";

export default function MyRentalsPage() {
    const [incoming, setIncoming] = useState<any[]>([]);
    const [myBorrows, setMyBorrows] = useState<any[]>([]);
    const [loading, setLoading] = useState(true);

    const userId = auth?.currentUser?.uid;

    useEffect(() => {
        if (!userId || !db) return;

        // Listen for Incoming Requests (Items I own)
        const incomingQuery = query(
            collection(db, "rentals"),
            where("ownerId", "==", userId),
            where("status", "in", ["requested", "approved", "overdue"])
        );

        const unsubscribeIncoming = onSnapshot(incomingQuery, (snapshot) => {
            const items = snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() }));
            setIncoming(items);
            setLoading(false);
        });

        // Listen for My Borrows (Items I'm renting)
        const borrowsQuery = query(
            collection(db, "rentals"),
            where("renterId", "==", userId)
        );

        const unsubscribeBorrows = onSnapshot(borrowsQuery, (snapshot) => {
            const items = snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() }));
            setMyBorrows(items);
        });

        return () => {
            unsubscribeIncoming();
            unsubscribeBorrows();
        };
    }, [userId]);

    const handleAction = async (rentalId: string, status: string) => {
        if (!db) return;
        try {
            const rentalRef = doc(db, "rentals", rentalId);
            if (status === "available") {
                // Rejecting - clear renterId
                await updateDoc(rentalRef, { status, renterId: null });
                toast.info("Request rejected");
            } else {
                await updateDoc(rentalRef, { status });
                toast.success(`Request ${status}`);
            }
        } catch (error) {
            console.error(error);
            toast.error("Action failed");
        }
    };

    const handleReport = async (item: any) => {
        if (!item.renterId || !db || !userId) return;

        const confirmReport = window.confirm("Are you sure you want to report this user? This will add 1 strike.");
        if (!confirmReport) return;

        try {
            // 1. Create Report
            await addDoc(collection(db, "reports"), {
                rentalId: item.id,
                renterId: item.renterId,
                ownerId: userId,
                reason: "Item not returned / Damaged",
                timestamp: serverTimestamp(),
            });

            // 2. Fetch Renter User Doc
            const renterRef = doc(db, "users", item.renterId);
            const renterSnap = await getDoc(renterRef);

            if (renterSnap.exists()) {
                const userData = renterSnap.data();
                const currentReports = (userData.reportsCount || 0) + 1;

                // 3. Increment strikes and check for block
                await updateDoc(renterRef, {
                    reportsCount: currentReports,
                    isBlocked: currentReports >= 2
                });

                if (currentReports >= 2) {
                    toast.error("User has been BLOCKED (2 strikes reached).");
                } else {
                    toast.warning("User reported. 1 strike added.");
                }
            }
        } catch (error) {
            console.error(error);
            toast.error("Failed to file report.");
        }
    };

    if (loading) return (
        <div className="flex-1 flex flex-col items-center justify-center min-h-screen bg-slate-50 text-indigo-600">
            <Loader2 className="w-10 h-10 animate-spin mb-4" />
            <p className="font-bold font-outfit text-xl">Loading Dashboard...</p>
        </div>
    );

    return (
        <div className="flex-1 flex flex-col bg-slate-50 relative min-h-screen pb-32 overflow-y-auto">
            {/* Ambient Background Blobs */}
            <div className="fixed top-[-10%] left-[-10%] w-[50%] h-[50%] bg-blue-200/40 blob rounded-full mix-blend-multiply filter blur-3xl animate-float pointer-events-none" style={{ animationDelay: "0s" }} />
            <div className="fixed top-[20%] right-[-10%] w-[40%] h-[60%] bg-pink-200/30 blob rounded-full mix-blend-multiply filter blur-3xl animate-float pointer-events-none" style={{ animationDelay: "2s" }} />
            <div className="fixed bottom-[-10%] left-[20%] w-[60%] h-[40%] bg-purple-200/30 blob rounded-full mix-blend-multiply filter blur-3xl animate-float pointer-events-none" style={{ animationDelay: "4s" }} />

